import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Tensor-core WMMA attention specialized for the reference shapes:
//   Q, K, V : (2, 32, 256, 1024) fp16, contiguous
//   out = softmax(Q @ K^T * (1/sqrt(1024))) @ V
// One warp handles 16 query rows for one batch*head. WMMA m16n16k16 is used
// for both QK^T and P@V; K tiles are naturally column-major for row.col WMMA,
// and V tiles are staged row-major with 16-byte vector copies and fed to mma via ldmatrix.trans.
.visible .entry attention_kernel(
    .param .u64 pQ,
    .param .u64 pK,
    .param .u64 pV,
    .param .u64 pO
)
{
    .reg .pred %p<24>;
    .reg .b16 %rh<32>;
    .reg .b32 %r<128>;
    .reg .b64 %rd<32>;
    .reg .f32 %f<128>;
    .shared .align 16 .f32 scores[4096];   // 16 x 256 fp32
    .shared .align 16 .b16 psm[4096];      // 16 x 256 fp16 normalized probabilities
    .shared .align 16 .b16 atile[256];     // 16 x 16 fp16 A tile
    .shared .align 16 .b16 btile[256];     // 16 x 16 fp16 B tile
    .shared .align 16 .b16 vtile[256];     // transposed 16 x 16 fp16 V tile
    .shared .align 16 .f32 otile[256];     // 16 x 16 fp32 output tile
    ld.param.u64 %rd0, [pQ];
    ld.param.u64 %rd1, [pK];
    ld.param.u64 %rd2, [pV];
    ld.param.u64 %rd3, [pO];
    mov.u32 %r0, %tid.x;              // lane 0..31
    mov.u32 %r1, %ctaid.x;            // 16-row query block, 0..15
    mov.u32 %r2, %ctaid.y;            // bh = batch*32 + head
    shl.b32 %r3, %r1, 4;              // q0 = qblock*16
    shl.b32 %r4, %r2, 18;             // bh*262144 elements
    shl.b32 %r5, %r3, 10;             // q0*1024
    add.u32 %r6, %r4, %r5;            // global Q/O element base for these 16 rows
    shl.b32 %r7, %r0, 3;              // lane*8
    mov.u32 %r8, scores;
    mov.u32 %r9, psm;
    mov.u32 %r10, atile;
    mov.u32 %r11, btile;
    mov.u32 %r12, vtile;
    mov.u32 %r13, otile;
    // ---------------- pass 1: S = Q K^T, 16 n-tiles of 16 keys ----------------
    mov.u32 %r14, 0;                  // ntile 0..15
NT_LOOP:
    shl.b32 %r15, %r14, 4;            // n0 = ntile*16
    // zero C fragment
    mov.f32 %f64, 0f00000000;
    mov.f32 %f65, 0f00000000;
    mov.f32 %f66, 0f00000000;
    mov.f32 %f67, 0f00000000;
    mov.f32 %f68, 0f00000000;
    mov.f32 %f69, 0f00000000;
    mov.f32 %f70, 0f00000000;
    mov.f32 %f71, 0f00000000;
    mov.u32 %r16, 0;                  // ktile 0..63
QK_K_LOOP:
    shl.b32 %r17, %r16, 4;            // k0 = ktile*16
    // stage A=Q[0:16,k0:k0+16] and B=K[n0:n0+16,k0:k0+16] with one 16B vector copy per lane
    // lane -> row = lane/2, colbase = (lane&1)*8 (8 contiguous halves = 16 bytes)
    shr.u32 %r18, %r0, 1;             // row 0..15
    and.b32 %r19, %r0, 1;
    shl.b32 %r19, %r19, 3;            // colbase 0 or 8
    shl.b32 %r20, %r18, 5;            // row*32 bytes
    shl.b32 %r21, %r19, 1;            // colbase*2 bytes
    add.u32 %r20, %r20, %r21;         // 16B-aligned shared tile offset
    // A from Q row q0+row, dim k0+colbase
    add.u32 %r24, %r3, %r18;          // q row
    shl.b32 %r24, %r24, 10;           // *1024
    add.u32 %r24, %r24, %r4;          // + bh base
    add.u32 %r25, %r17, %r19;         // k0+colbase
    add.u32 %r24, %r24, %r25;         // global element
    shl.b32 %r24, %r24, 1;
    cvt.u64.u32 %rd4, %r24;
    add.u64 %rd4, %rd4, %rd0;
    ld.global.v4.b32 {%r44,%r45,%r46,%r47}, [%rd4];
    add.u32 %r26, %r10, %r20;
    st.shared.v4.b32 [%r26], {%r44,%r45,%r46,%r47};
    // B from K key n0+row, dim k0+colbase; btile stays n-major with k contiguous
    add.u32 %r27, %r15, %r18;         // key row
    shl.b32 %r27, %r27, 10;
    add.u32 %r27, %r27, %r4;
    add.u32 %r27, %r27, %r25;
    shl.b32 %r27, %r27, 1;
    cvt.u64.u32 %rd5, %r27;
    add.u64 %rd5, %rd5, %rd1;
    ld.global.v4.b32 {%r48,%r49,%r50,%r51}, [%rd5];
    add.u32 %r28, %r11, %r20;
    st.shared.v4.b32 [%r28], {%r48,%r49,%r50,%r51};
    bar.warp.sync 0xffffffff;
    // lane addresses for the four 8x8 A matrices (16 rows x 16 k)
    and.b32 %r30, %r0, 15;
    shl.b32 %r30, %r30, 5;            // row*32 bytes
    shr.u32 %r31, %r0, 4;
    shl.b32 %r31, %r31, 4;            // k-half*16 bytes
    add.u32 %r30, %r30, %r31;
    add.u32 %r30, %r30, %r10;
    ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%r32,%r33,%r34,%r35}, [%r30];
    // btile is n-major with k contiguous, exactly the col-major B layout
    and.b32 %r30, %r0, 7;
    shr.u32 %r31, %r0, 4;
    shl.b32 %r31, %r31, 3;
    add.u32 %r30, %r30, %r31;
    shl.b32 %r30, %r30, 5;            // n*32 bytes
    shr.u32 %r31, %r0, 3;
    and.b32 %r31, %r31, 1;
    shl.b32 %r31, %r31, 4;            // k-half*16 bytes
    add.u32 %r30, %r30, %r31;
    add.u32 %r30, %r30, %r11;
    ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%r40,%r41,%r42,%r43}, [%r30];
    mma.sync.aligned.m16n8k16.row.col.f32.f16.f16.f32 {%f64,%f65,%f66,%f67}, {%r32,%r33,%r34,%r35}, {%r40,%r41}, {%f64,%f65,%f66,%f67};
    mma.sync.aligned.m16n8k16.row.col.f32.f16.f16.f32 {%f68,%f69,%f70,%f71}, {%r32,%r33,%r34,%r35}, {%r42,%r43}, {%f68,%f69,%f70,%f71};
    add.u32 %r16, %r16, 1;
    setp.lt.u32 %p1, %r16, 64;
    @%p1 bra QK_K_LOOP;
    // store the 16x16 score tile to scores[0:16, n0:n0+16], row stride 256 floats
    shl.b32 %r29, %r15, 2;            // n0 floats -> bytes
    add.u32 %r30, %r8, %r29;
    // store both m16n8 D fragments with the mma.sync per-lane mapping
    shr.u32 %r16, %r0, 2;             // first row
    and.b32 %r17, %r0, 3;
    shl.b32 %r17, %r17, 1;            // column pair in n8 tile
    add.u32 %r18, %r15, %r17;         // score column
    shl.b32 %r19, %r16, 8;            // row*256 floats
    add.u32 %r19, %r19, %r18;
    shl.b32 %r19, %r19, 2;
    add.u32 %r20, %r8, %r19;
    st.shared.v2.f32 [%r20], {%f64,%f65};
    add.u32 %r21, %r18, 8;            // second n8 half
    shl.b32 %r22, %r16, 8;
    add.u32 %r22, %r22, %r21;
    shl.b32 %r22, %r22, 2;
    add.u32 %r23, %r8, %r22;
    st.shared.v2.f32 [%r23], {%f68,%f69};
    add.u32 %r16, %r16, 8;            // second row half
    shl.b32 %r19, %r16, 8;
    add.u32 %r19, %r19, %r18;
    shl.b32 %r19, %r19, 2;
    add.u32 %r20, %r8, %r19;
    st.shared.v2.f32 [%r20], {%f66,%f67};
    shl.b32 %r22, %r16, 8;
    add.u32 %r22, %r22, %r21;
    shl.b32 %r22, %r22, 2;
    add.u32 %r23, %r8, %r22;
    st.shared.v2.f32 [%r23], {%f70,%f71};
    add.u32 %r14, %r14, 1;
    setp.lt.u32 %p2, %r14, 16;
    @%p2 bra NT_LOOP;
    bar.warp.sync 0xffffffff;
    // ---------------- softmax over 256 keys: 2 lanes/row, vectorized v4 shared I/O ----------------
    // all 32 lanes active; lane pair (2r,2r+1) handles row r, 128 elements each
    shr.u32 %r30, %r0, 1;             // row 0..15
    and.b32 %r31, %r0, 1;             // half selector
    shl.b32 %r32, %r30, 10;           // row*1024 bytes (scores row)
    shl.b32 %r33, %r31, 9;            // half*512 bytes (128 floats)
    add.u32 %r34, %r32, %r33;
    add.u32 %r34, %r34, %r8;          // lane scores base
    shl.b32 %r35, %r30, 9;            // row*512 bytes (psm row)
    shl.b32 %r36, %r31, 8;            // half*256 bytes (128 halves)
    add.u32 %r37, %r35, %r36;
    add.u32 %r37, %r37, %r9;          // lane psm base
    mov.f32 %f72, 0fFF800000;         // max = -inf
    mov.u32 %r38, 0;
VMAX_LOOP:
    shl.b32 %r39, %r38, 4;            // i*16 bytes (4 floats)
    add.u32 %r39, %r39, %r34;
    ld.shared.v4.f32 {%f80,%f81,%f82,%f83}, [%r39];
    max.f32 %f72, %f72, %f80;
    max.f32 %f72, %f72, %f81;
    max.f32 %f72, %f72, %f82;
    max.f32 %f72, %f72, %f83;
    add.u32 %r38, %r38, 1;
    setp.lt.u32 %p4, %r38, 32;
    @%p4 bra VMAX_LOOP;
    shfl.sync.bfly.b32 %f73, %f72, 1, 0x1f, 0xffffffff;
    max.f32 %f72, %f72, %f73;         // row max in both lanes
    mov.f32 %f74, 0f00000000;         // sum
    mov.u32 %r38, 0;
VSUM_LOOP:
    shl.b32 %r39, %r38, 4;
    add.u32 %r39, %r39, %r34;
    ld.shared.v4.f32 {%f80,%f81,%f82,%f83}, [%r39];
    sub.f32 %f80, %f80, %f72;
    sub.f32 %f81, %f81, %f72;
    sub.f32 %f82, %f82, %f72;
    sub.f32 %f83, %f83, %f72;
    mul.f32 %f80, %f80, 0f3D000000;
    mul.f32 %f81, %f81, 0f3D000000;
    mul.f32 %f82, %f82, 0f3D000000;
    mul.f32 %f83, %f83, 0f3D000000;
    mul.f32 %f80, %f80, 0f3FB8AA3B;
    mul.f32 %f81, %f81, 0f3FB8AA3B;
    mul.f32 %f82, %f82, 0f3FB8AA3B;
    mul.f32 %f83, %f83, 0f3FB8AA3B;
    ex2.approx.f32 %f80, %f80;
    ex2.approx.f32 %f81, %f81;
    ex2.approx.f32 %f82, %f82;
    ex2.approx.f32 %f83, %f83;
    add.f32 %f74, %f74, %f80;
    add.f32 %f74, %f74, %f81;
    add.f32 %f74, %f74, %f82;
    add.f32 %f74, %f74, %f83;
    st.shared.v4.f32 [%r39], {%f80,%f81,%f82,%f83};
    add.u32 %r38, %r38, 1;
    setp.lt.u32 %p5, %r38, 32;
    @%p5 bra VSUM_LOOP;
    shfl.sync.bfly.b32 %f75, %f74, 1, 0x1f, 0xffffffff;
    add.f32 %f74, %f74, %f75;         // row sum in both lanes
    mov.f32 %f77, 0f3F800000;
    div.rn.f32 %f78, %f77, %f74;      // 1/sum
    mov.u32 %r38, 0;
VNORM_LOOP:
    shl.b32 %r39, %r38, 4;
    add.u32 %r39, %r39, %r34;
    ld.shared.v4.f32 {%f80,%f81,%f82,%f83}, [%r39];
    mul.f32 %f80, %f80, %f78;
    mul.f32 %f81, %f81, %f78;
    mul.f32 %f82, %f82, %f78;
    mul.f32 %f83, %f83, %f78;
    cvt.rn.f16.f32 %rh10, %f80;
    cvt.rn.f16.f32 %rh11, %f81;
    cvt.rn.f16.f32 %rh12, %f82;
    cvt.rn.f16.f32 %rh13, %f83;
    mov.b32 %r40, {%rh10, %rh11};
    mov.b32 %r41, {%rh12, %rh13};
    shl.b32 %r42, %r38, 3;            // 4 halves = 8 bytes
    add.u32 %r42, %r42, %r37;
    st.shared.v2.b32 [%r42], {%r40,%r41};
    add.u32 %r38, %r38, 1;
    setp.lt.u32 %p6, %r38, 32;
    @%p6 bra VNORM_LOOP;
SOFTMAX_DONE:
    bar.warp.sync 0xffffffff;
    // ---------------- pass 2: O = P V, output tiles are 16 rows x 16 dims ----------------
    mov.u32 %r14, 0;                  // output dim ntile 0..63
PV_N_LOOP:
    shl.b32 %r15, %r14, 4;            // n0 = dim tile*16
    mov.f32 %f64, 0f00000000;
    mov.f32 %f65, 0f00000000;
    mov.f32 %f66, 0f00000000;
    mov.f32 %f67, 0f00000000;
    mov.f32 %f68, 0f00000000;
    mov.f32 %f69, 0f00000000;
    mov.f32 %f70, 0f00000000;
    mov.f32 %f71, 0f00000000;
    mov.u32 %r16, 0;                  // key ktile 0..15
PV_K_LOOP:
    shl.b32 %r17, %r16, 4;            // k0 = key tile*16
    // stage V tile in natural row-major layout vtile[key*16+dim] = V[k0+key, n0+dim]
    // one 16B vector copy per lane; ldmatrix.trans below handles the B-operand transpose
    shr.u32 %r18, %r0, 1;             // key 0..15
    and.b32 %r19, %r0, 1;
    shl.b32 %r19, %r19, 3;            // dimbase 0 or 8
    shl.b32 %r20, %r18, 5;            // key*32 bytes
    shl.b32 %r21, %r19, 1;
    add.u32 %r20, %r20, %r21;         // 16B-aligned shared offset
    add.u32 %r24, %r17, %r18;         // global key
    shl.b32 %r24, %r24, 10;
    add.u32 %r24, %r24, %r4;
    add.u32 %r25, %r15, %r19;         // global dim
    add.u32 %r24, %r24, %r25;
    shl.b32 %r24, %r24, 1;
    cvt.u64.u32 %rd6, %r24;
    add.u64 %rd6, %rd6, %rd2;
    ld.global.v4.b32 {%r44,%r45,%r46,%r47}, [%rd6];
    add.u32 %r26, %r12, %r20;
    st.shared.v4.b32 [%r26], {%r44,%r45,%r46,%r47};
    // A = P[0:16, k0:k0+16], row-major stride 256 halves
    shl.b32 %r27, %r17, 1;            // k0 halves -> bytes
    add.u32 %r28, %r9, %r27;
    bar.warp.sync 0xffffffff;
    // A fragment from psm; lane addresses select 16 rows and two k-halves
    and.b32 %r30, %r0, 15;
    shl.b32 %r30, %r30, 9;            // row*512 bytes
    shl.b32 %r27, %r17, 1;            // k0 halves -> bytes
    add.u32 %r30, %r30, %r27;
    shr.u32 %r31, %r0, 4;
    shl.b32 %r31, %r31, 4;
    add.u32 %r30, %r30, %r31;
    add.u32 %r30, %r30, %r9;
    ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%r32,%r33,%r34,%r35}, [%r30];
    // vtile is row-major [key][dim]; ldmatrix.trans yields the col-major B fragment
    // lanes 0-7 -> k0-7/n0-7, 8-15 -> k8-15/n0-7, 16-23 -> k0-7/n8-15, 24-31 -> k8-15/n8-15
    shr.u32 %r30, %r0, 3;
    and.b32 %r30, %r30, 1;            // k-half selector
    shl.b32 %r30, %r30, 3;
    and.b32 %r31, %r0, 7;
    add.u32 %r30, %r30, %r31;         // k row 0..15
    shl.b32 %r30, %r30, 5;            // *32 bytes (16 halves per row)
    shr.u32 %r31, %r0, 4;             // n-half selector
    shl.b32 %r31, %r31, 4;            // *16 bytes
    add.u32 %r30, %r30, %r31;
    add.u32 %r30, %r30, %r12;
    ldmatrix.sync.aligned.m8n8.x4.trans.shared.b16 {%r40,%r41,%r42,%r43}, [%r30];
    mma.sync.aligned.m16n8k16.row.col.f32.f16.f16.f32 {%f64,%f65,%f66,%f67}, {%r32,%r33,%r34,%r35}, {%r40,%r41}, {%f64,%f65,%f66,%f67};
    mma.sync.aligned.m16n8k16.row.col.f32.f16.f16.f32 {%f68,%f69,%f70,%f71}, {%r32,%r33,%r34,%r35}, {%r42,%r43}, {%f68,%f69,%f70,%f71};
    add.u32 %r16, %r16, 1;
    setp.lt.u32 %p8, %r16, 16;
    @%p8 bra PV_K_LOOP;
    // convert D fragments to half2 and store directly to global O
    shr.u32 %r16, %r0, 2;             // row 0..7
    and.b32 %r17, %r0, 3;
    shl.b32 %r17, %r17, 1;            // col pair 0,2,4,6
    add.u32 %r18, %r15, %r17;         // first n8 global col
    add.u32 %r19, %r18, 8;            // second n8 global col
    shl.b32 %r20, %r16, 10;           // row*1024
    add.u32 %r21, %r6, %r20;          // element base row
    add.u32 %r22, %r21, 8192;         // row+8 base
    add.u32 %r23, %r21, %r18;         // row, first n8
    add.u32 %r24, %r22, %r18;         // row+8, first n8
    add.u32 %r25, %r21, %r19;         // row, second n8
    add.u32 %r26, %r22, %r19;         // row+8, second n8
    shl.b32 %r23, %r23, 1;
    shl.b32 %r24, %r24, 1;
    shl.b32 %r25, %r25, 1;
    shl.b32 %r26, %r26, 1;
    cvt.u64.u32 %rd4, %r23;
    add.u64 %rd4, %rd4, %rd3;
    cvt.u64.u32 %rd5, %r24;
    add.u64 %rd5, %rd5, %rd3;
    cvt.u64.u32 %rd6, %r25;
    add.u64 %rd6, %rd6, %rd3;
    cvt.u64.u32 %rd7, %r26;
    add.u64 %rd7, %rd7, %rd3;
    cvt.rn.f16.f32 %rh8, %f64;
    cvt.rn.f16.f32 %rh9, %f65;
    cvt.rn.f16.f32 %rh10, %f66;
    cvt.rn.f16.f32 %rh11, %f67;
    cvt.rn.f16.f32 %rh12, %f68;
    cvt.rn.f16.f32 %rh13, %f69;
    cvt.rn.f16.f32 %rh14, %f70;
    cvt.rn.f16.f32 %rh15, %f71;
    mov.b32 %r35, {%rh8, %rh9};
    mov.b32 %r36, {%rh10, %rh11};
    mov.b32 %r37, {%rh12, %rh13};
    mov.b32 %r38, {%rh14, %rh15};
    st.global.b32 [%rd4], %r35;
    st.global.b32 [%rd5], %r36;
    st.global.b32 [%rd6], %r37;
    st.global.b32 [%rd7], %r38;
    add.u32 %r14, %r14, 1;
    setp.lt.u32 %p9, %r14, 64;
    @%p9 bra PV_N_LOOP;
