        module.launch(
            "attention_kernel",
            grid=(sequence_length // 16, batch_size * num_heads, 1),
            block=(32, 1, 1),
            arguments=[Q, K, V, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
